// Single source of truth for the NDA wording shown to investors when signing
// (web + mobile) and reproduced verbatim on the downloadable signed-NDA record
// generated by the API server. Edit ONLY this file to change the NDA terms.

export const NDA_TITLE = "Non-Disclosure Agreement";

export const NDA_PREAMBLE =
  "This Non-Disclosure Agreement governs your access to confidential information concerning the investment opportunity marketed through RealEstate Vault.";

export const NDA_CLAUSES = [
  "You agree to keep all deal materials — including pricing, tenancy schedules, financial models, and the identity or location of the asset — strictly confidential.",
  "Confidential information may be used solely to evaluate a potential acquisition and may not be shared with third parties without the listing broker's prior written consent.",
  "This obligation remains in force for 24 months from the date of signature or until the information becomes public through no fault of your own.",
  "By signing electronically below, you confirm you are authorised to bind yourself and your firm to these terms.",
];

/**
 * The full NDA body as an ordered list of paragraphs: the preamble followed by
 * the numbered clauses ("1. ...", "2. ...", ...). Convenient for UIs that
 * render the terms as a simple sequence of paragraphs.
 */
export const NDA_PARAGRAPHS = [
  NDA_PREAMBLE,
  ...NDA_CLAUSES.map((clause, i) => `${i + 1}. ${clause}`),
];
